#!/usr/bin/env bash
# Upgrade test for one platform chart, on a throwaway kind cluster (upstream Kubernetes, no distro add-ons) (CI job "Upgrade" in charts-test.yaml):
#   1. its dependencies, from the base ref (CI: latest release tag);
#   2. the chart, from the base ref;
#   3. helm upgrade to this working tree.
# Pass: rollouts done, pods Ready, Jobs complete, Certificates / ExternalSecrets / CNPG Clusters Ready,
# and the secrets generated by External Secrets unchanged by the upgrade.
# Usage: bash hack/chart-upgrade-test.sh helm/platform/<chart> [base-ref, default: latest v* tag]   (KEEP=1 keeps the cluster)
set -euo pipefail
CHART=${1:?usage: hack/chart-upgrade-test.sh helm/platform/<chart> [base-ref]}
BASE_REF=${2:-$(git -C "$(dirname "$0")" describe --tags --abbrev=0 --match "v*" origin/main)}
ROOT=$(cd "$(dirname "$0")/.." && pwd)
n=$(basename "$CHART")
TIMEOUT=${TIMEOUT:-15m}
NODE_IMAGE=${NODE_IMAGE:-kindest/node:v1.37.0}
# renovate: datasource=docker depName=registry.k8s.io/cloud-provider-kind/cloud-controller-manager
CPK_VERSION=v0.12.0
CLUSTER=${CLUSTER:-upg-$n}

# Installed (from the base branch) before the chart.
declare -A DEPS=(
  [cloudnative-pg]="cert-manager"
  [seaweedfs]="openebs external-secrets"
  [monitoring]="openebs external-secrets seaweedfs"
  [infisical]="openebs cert-manager cloudnative-pg external-secrets seaweedfs"
)
# Only their CRDs (Gateway API from traefik: cert-manager enableGatewayAPI, HTTPRoutes; PodMonitor from monitoring).
declare -A CRDS=(
  [argocd]="traefik"
  [cert-manager]="traefik"
  [cloudnative-pg]="traefik"
  [monitoring]="traefik"
  [infisical]="traefik monitoring"
)

appset=$ROOT/argocd/applications/platform/appset.yaml
ns_of() { yq -r ".spec.generators[0].list.elements[] | select(.app == \"$1\") | .namespace" "$appset"; }
ns=$(ns_of "$n")
[ -n "$ns" ] || { echo "$n is not in the platform ApplicationSet: skipped"; exit 0; }
# cilium replaces the CNI of the node: not testable on a shared kind cluster.
[ "$n" != cilium ] || { echo "cilium: skipped (CNI)"; exit 0; }

tmp=$(mktemp -d)
export KUBECONFIG=$tmp/kubeconfig
cleanup() {
  [ "${KEEP:-}" = 1 ] && { echo "kept: kind cluster $CLUSTER, KUBECONFIG=$KUBECONFIG"; return; }
  kind delete cluster --name "$CLUSTER" >/dev/null 2>&1 || true
  docker rm -f cloud-provider-kind >/dev/null 2>&1 || true
  git -C "$ROOT" worktree remove --force "$tmp/base" >/dev/null 2>&1 || true
  rm -rf "$tmp"
}
diagnose() {
  echo "::group::diagnostics"
  kubectl get pods -A -o wide || true
  kubectl get events -A --sort-by=.lastTimestamp | tail -40 || true
  kubectl get pods -A -o json | jq -r '.items[] | select(.status.phase != "Succeeded")
    | select(([.status.containerStatuses[]?.ready] | all) | not) | "\(.metadata.namespace) \(.metadata.name)"' |
    while read -r pns pod; do
      kubectl -n "$pns" describe pod "$pod" | tail -25
      kubectl -n "$pns" logs "$pod" --all-containers --tail=40 || true
    done
  echo "::endgroup::"
}
trap 'rc=$?; set +e; [ "$rc" = 0 ] || diagnose; cleanup; exit "$rc"' EXIT

summary() { echo "$*"; [ -z "${GITHUB_STEP_SUMMARY:-}" ] || echo "$*" >> "$GITHUB_STEP_SUMMARY"; }

render() { # <root> <chart>: rendered manifests, CRDs included
  local d=$1/helm/platform/$2
  helm dependency build "$d" >/dev/null 2>&1 || helm dependency update "$d" >/dev/null
  helm template "$2" "$d" -n "$(ns_of "$2")" -f "$1/cluster.yaml" --include-crds
}

apply_crds() { # <root> <chart>: like ArgoCD, apply (and upgrade) CRDs; Helm never upgrades crds/
  local crds
  crds=$(render "$1" "$2" | yq "select(.kind == \"CustomResourceDefinition\")
    | .metadata.labels.\"app.kubernetes.io/managed-by\" = \"Helm\"
    | .metadata.annotations.\"meta.helm.sh/release-name\" = \"$2\"
    | .metadata.annotations.\"meta.helm.sh/release-namespace\" = \"$(ns_of "$2")\"")
  [ -z "$crds" ] || kubectl apply --server-side --force-conflicts -f - <<<"$crds" >/dev/null
}

deploy() { # <root> <chart>
  local cns
  cns=$(ns_of "$2")
  apply_crds "$1" "$2"
  # ArgoCD hook Jobs (BeforeHookCreation): delete them before re-creating
  kubectl -n "$cns" get jobs -o json |
    jq -r '.items[] | select(.metadata.annotations["argocd.argoproj.io/hook"]) | .metadata.name' |
    xargs -r kubectl -n "$cns" delete job --wait
  local i
  for i in 1 2 3; do # admission webhooks of a fresh operator may need a few seconds
    helm upgrade --install "$2" "$1/helm/platform/$2" -n "$cns" -f "$1/cluster.yaml" \
      --skip-crds --wait --timeout "$TIMEOUT" && return 0
    [ "$i" = 3 ] || sleep 20
  done
  return 1
}

# Operators: a resource they manage, created before the upgrade, must stay Ready after it.
fixture() {
  case $n in
  cloudnative-pg)
    kubectl create ns cnpg-test >/dev/null
    kubectl apply -f - >/dev/null <<'EOF'
apiVersion: postgresql.cnpg.io/v1
kind: Cluster
metadata: {name: pg, namespace: cnpg-test}
spec: {instances: 1, storage: {size: 1Gi}}
EOF
    echo cnpg-test ;;
  external-secrets)
    kubectl create ns eso-test >/dev/null
    kubectl apply -f - >/dev/null <<'EOF'
apiVersion: external-secrets.io/v1
kind: ExternalSecret
metadata: {name: generated, namespace: eso-test}
spec:
  refreshInterval: "0"
  target: {name: generated}
  dataFrom:
    - sourceRef:
        generatorRef: {apiVersion: generators.external-secrets.io/v1alpha1, kind: ClusterGenerator, name: password-cluster-generator}
EOF
    echo eso-test ;;
  esac
}

ready() { # <namespace>
  local r k deadline=$((SECONDS + 900)) bad
  for r in $(kubectl -n "$1" get deploy,sts,ds -o name); do
    kubectl -n "$1" rollout status "$r" --timeout="$TIMEOUT" >/dev/null
  done
  for k in certificates.cert-manager.io externalsecrets.external-secrets.io clusters.postgresql.cnpg.io jobs; do
    kubectl get "$k" -A >/dev/null 2>&1 || continue
    [ -z "$(kubectl -n "$1" get "$k" -o name)" ] && continue
    if [ "$k" = jobs ]; then
      kubectl -n "$1" wait jobs --all --for=condition=Complete --timeout="$TIMEOUT" >/dev/null
    else
      kubectl -n "$1" wait "$k" --all --for=condition=Ready --timeout="$TIMEOUT" >/dev/null
    fi
  done
  while :; do # every pod Ready, except Job pods (checked above)
    bad=$(kubectl -n "$1" get pods -o json | jq -r '.items[]
      | select(any(.metadata.ownerReferences[]?; .kind == "Job") | not)
      | select(.status.phase != "Running" or (([.status.containerStatuses[]?.ready] | all) | not))
      | .metadata.name')
    [ -z "$bad" ] && break
    [ "$SECONDS" -lt "$deadline" ] || { echo "pods not Ready in $1: $bad"; return 1; }
    sleep 10
  done
}

hashes() { # <namespace>: name + short sha256 of each Secret written by an ExternalSecret (values never printed)
  kubectl -n "$1" get secrets -o json |
    jq -r '.items[] | select(any(.metadata.ownerReferences[]?; .kind == "ExternalSecret"))
      | "\(.metadata.name) \(.data | tostring | @base64)"' |
    while read -r s d; do echo "$s $(printf %s "$d" | sha256sum | cut -c1-12)"; done | sort
}

t0=$SECONDS
git -C "$ROOT" worktree add --detach "$tmp/base" "$BASE_REF" >/dev/null 2>&1
BASE=$tmp/base
kind create cluster --name "$CLUSTER" --image "$NODE_IMAGE" --wait 180s >/dev/null 2>&1
# LoadBalancer Services (traefik): the kind cloud provider, like a cloud or MetalLB would
docker ps -q -f name=cloud-provider-kind | grep -q . ||
  docker run -d --rm --name cloud-provider-kind --network kind -v /var/run/docker.sock:/var/run/docker.sock \
    "registry.k8s.io/cloud-provider-kind/cloud-controller-manager:$CPK_VERSION" --gateway-channel disabled >/dev/null # Gateway API comes from kinops
for x in $(yq -r '.spec.generators[0].list.elements[].namespace' "$appset" | sort -u); do
  kubectl create ns "$x" --dry-run=client -o yaml | kubectl apply -f - >/dev/null
done
summary "### Upgrade $n ($BASE_REF -> $(git -C "$ROOT" rev-parse --short HEAD))"
summary "- cluster: $((SECONDS - t0))s"

t=$SECONDS
for d in ${CRDS[$n]:-}; do apply_crds "$BASE" "$d"; done
for d in ${DEPS[$n]:-}; do deploy "$BASE" "$d"; ready "$(ns_of "$d")"; done
summary "- dependencies (${DEPS[$n]:-none}; CRDs: ${CRDS[$n]:-none}): $((SECONDS - t))s"

check=$ns before=
if [ -d "$BASE/helm/platform/$n" ]; then
  t=$SECONDS
  deploy "$BASE" "$n"; ready "$ns"
  f=$(fixture); [ -z "$f" ] || { check="$ns $f"; ready "$f"; }
  before=$(for x in $check; do hashes "$x"; done)
  summary "- install $n from $BASE_REF${f:+ + test resources in $f}: $((SECONDS - t))s"
else
  summary "- $n is new: install only"
fi

t=$SECONDS
deploy "$ROOT" "$n"
for x in $check; do ready "$x"; done
summary "- upgrade $n: $((SECONDS - t))s"

after=$(for x in $check; do hashes "$x"; done)
if [ -n "$before" ] && [ "$before" != "$after" ]; then
  diff <(echo "$before") <(echo "$after") || true
  summary "- FAIL: generated secrets changed on upgrade"
  exit 1
fi
summary "- generated secrets unchanged: $(grep -c . <<<"$after" || true)"
summary "- PASS in $((SECONDS - t0))s"
